      description: 'Error message shown when the value is invalid.',
      type: 'string',
      required: false,
    },
    {
      name: 'size',
      description: "Visual size of the component (e.g. 'sm', 'md', 'lg').",
      type: "'sm' | 'md' | 'lg'",
      required: false,
      default: 'md',
    },
    {
      name: 'disabled',
      description: 'When true, disables the control and removes it from the tab order.',
      type: 'boolean',
      required: false,
      default: 'false',
    },
    {
      name: 'incrementLabel',
      description: 'Accessible label for the increment button.',
      type: 'string',
      required: false,
      default: 'Increment',
    },
    {
      name: 'decrementLabel',
      description: 'Accessible label for the decrement button.',
      type: 'string',
      required: false,
      default: 'Decrement',
    },
    {
      name: 'ariaLabel',
      description:
        'Invisible accessible name, for when a visible element outside this component already labels it and `label` would render that text a second time. ⚠ `label` on this component is **visible**; `IconButton.label`/`Sparkline.label` are invisible names, which is the prior that costs adopters a duplicated label. The raw DOM `aria-label` still wins over this.',
      type: 'string',
      required: false,
      nameVisibility: 'invisible',
    },
  ],
  tokens: [
    '--cascivo-color-surface',
    '--cascivo-color-border',
    '--cascivo-color-accent',
    '--cascivo-color-destructive',
    '--cascivo-color-bg-subtle',
    '--cascivo-color-text-subtle',
    '--cascivo-radius-input',
    '--cascivo-focus-ring',
  ],
  accessibility: {
    role: 'spinbutton',
    wcag: '2.2-AA',
    keyboard: ['ArrowUp', 'ArrowDown', 'Enter', 'Tab'],
  },
  examples: [
    { title: 'Basic', code: '<NumberInput label="Quantity" defaultValue={1} min={0} max={99} />' },
    {
      title: 'Currency',
      code: '<NumberInput label="Price" precision={2} formatOptions={{ style: "currency", currency: "USD" }} />',
    },
    { title: 'Stepped', code: '<NumberInput label="Opacity" min={0} max={1} step={0.1} />' },
  ],
  dependencies: ['@cascivo/core', '@cascivo/i18n'],
  tags: ['form', 'number', 'input', 'spinbutton', 'stepper'],
  intent: {
    whenToUse: [
      'Collecting a bounded numeric value where increment/decrement by a known step is natural (quantity, opacity, count)',
      'Numeric entry that needs clamping to min/max, fixed precision, or locale-aware display formatting (e.g. currency)',
      'Inputs where keyboard ArrowUp/ArrowDown stepping speeds up adjustment',
    ],
    whenNotToUse: [
      'Free-form or non-numeric text — use Input',
      'Choosing along a continuous range where the exact number matters less than the relative position — use Slider',
      'Phone numbers, PINs, or codes that are digit strings rather than quantities — use Input or OtpInput',
